const neuronPartes=[{"desc": "Pesa cada rama por su probabilidad y suma", "ans": "El valor esperado", "opts": ["El valor esperado", "La utilidad", "El riesgo de ruina", "La ley de los grandes números"]}, {"desc": "Dice que cada lempira nuevo vale menos que el anterior", "ans": "La utilidad marginal decreciente", "opts": ["La utilidad marginal decreciente", "El valor esperado", "La paradoja de Allais", "La apuesta única"]}, {"desc": "La pérdida que impide jugar la vez siguiente", "ans": "El riesgo de ruina", "opts": ["El riesgo de ruina", "Una racha mala", "El costo del seguro", "La apuesta partida"]}, {"desc": "Garantiza que lo observado se acerque a lo esperado si se repite mucho", "ans": "La ley de los grandes números", "opts": ["La ley de los grandes números", "La paradoja de San Petersburgo", "Los axiomas de 1944", "La teoría de las perspectivas"]}, {"desc": "Un juego con valor esperado infinito que nadie compra caro", "ans": "La paradoja de San Petersburgo", "opts": ["La paradoja de San Petersburgo", "La paradoja de Allais", "El criterio de Kelly", "El dilema del seguro"]}, {"desc": "Preferencias reales que contradicen los axiomas de la utilidad esperada", "ans": "La paradoja de Allais", "opts": ["La paradoja de Allais", "La paradoja de San Petersburgo", "La ley de los grandes números", "La utilidad decreciente"]}, {"desc": "Una apuesta con la cuenta en contra que conviene comprar", "ans": "El seguro", "opts": ["El seguro", "La lotería", "La rifa del colegio", "El préstamo"]}, {"desc": "Jugar una fracción para que la rama mala no saque de la mesa", "ans": "Partir la apuesta", "opts": ["Partir la apuesta", "Doblar la apuesta", "Repetir la apuesta", "Cancelar la apuesta"]}];
let neuronIdx=0,neuronDone=false;
function showNeuron(){neuronDone=false;if(neuronIdx>=neuronPartes.length){const el=document.getElementById('neuronDesc');if(el)el.textContent='🎉 ¡Todos los conceptos identificados!';const opts=document.getElementById('neuronOpts');if(opts)opts.innerHTML='';fin('s-widgets');return;}const d=neuronPartes[neuronIdx];const prog=document.getElementById('neuronProg');if(prog)prog.textContent=`Concepto ${neuronIdx+1} de ${neuronPartes.length}`;const desc=document.getElementById('neuronDesc');if(desc)desc.textContent=d.desc;const opts=document.getElementById('neuronOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='cmp-opt';b.textContent=opt;b.onclick=()=>checkNeuron(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbNeuron');if(fbEl)fbEl.classList.remove('show');}
function checkNeuron(opt,btn,d){if(neuronDone)return;neuronDone=true;document.querySelectorAll('#neuronOpts .cmp-opt').forEach(b=>{if(b.textContent===d.ans)b.classList.add('correct');else if(b===btn&&b.textContent!==d.ans)b.classList.add('wrong');});const isOk=opt===d.ans;if(isOk){fb('fbNeuron','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('neuron_'+neuronIdx)){xpTracker.wgt.add('neuron_'+neuronIdx);pts(3);}sfx('ok');}else{fb('fbNeuron','La respuesta correcta es: '+d.ans,false);sfx('no');}}
function nextNeuron(){sfx('click');neuronIdx++;showNeuron();}
function resetNeuron(){sfx('click');neuronIdx=0;showNeuron();}

