// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s": "Pesa cada rama por su probabilidad y suma.", "type": "El valor esperado"}, {"s": "Cada lempira nuevo vale menos que el anterior.", "type": "La utilidad marginal decreciente"}, {"s": "La pérdida que impide jugar la vez siguiente.", "type": "El riesgo de ruina"}, {"s": "Quien juega una vez recibe una rama, no un promedio.", "type": "La apuesta única"}, {"s": "Lo observado se acerca a lo esperado si se repite mucho.", "type": "La ley de los grandes números"}, {"s": "Un juego con esperanza infinita que nadie compra caro.", "type": "La paradoja de San Petersburgo"}, {"s": "Preferencias reales que contradicen los axiomas de 1944.", "type": "La paradoja de Allais"}, {"s": "Una apuesta con la cuenta en contra que conviene comprar.", "type": "El seguro"}, {"s": "Jugar una fracción para que haya vez siguiente.", "type": "Partir la apuesta"}, {"s": "Se juzga por cómo se decidió, no por cómo cayó el dado.", "type": "La regla del proceso"}];
const classifyTaskDB=[{"w": "Multiplicar cada rama por su probabilidad", "gen": "Aritmética", "n": "Se hace con lápiz", "g": "Paso 4", "t": "Cuenta"}, {"w": "Listar todas las ramas posibles", "gen": "Aritmética", "n": "Incluida la aburrida", "g": "Paso 1", "t": "Cuenta"}, {"w": "Que las probabilidades sumen uno", "gen": "Aritmética", "n": "Control básico", "g": "Paso 2", "t": "Cuenta"}, {"w": "Sumar los productos de las ramas", "gen": "Aritmética", "n": "El resultado es el valor esperado", "g": "Paso 4", "t": "Cuenta"}, {"w": "¿Esta apuesta se va a repetir?", "gen": "Criterio", "n": "No está en la fórmula", "g": "Paso 5", "t": "Criterio"}, {"w": "¿La rama mala nos saca de la mesa?", "gen": "Criterio", "n": "No está en la fórmula", "g": "Paso 6", "t": "Criterio"}, {"w": "¿Se arriesga lo que sobra o lo que se necesita?", "gen": "Criterio", "n": "Pregunta de tamaño", "g": "Paso 6", "t": "Criterio"}, {"w": "¿Hay aquí algo que no se cambia por dinero?", "gen": "Criterio", "n": "Confianza, marca, horas", "g": "Paso 3", "t": "Criterio"}, {"w": "Guardar la hoja con la fecha", "gen": "Criterio", "n": "Antes del resultado", "g": "Paso 7", "t": "Criterio"}, {"w": "Anotar lo que gana o pierde cada rama", "gen": "Aritmética", "n": "En dos columnas", "g": "Paso 3", "t": "Cuenta"}];
const completeTaskDB=[{"s": "Nicolás Bernoulli planteó la paradoja en ___.", "opts": ["1713", "1738", "1944"], "ans": "1713"}, {"s": "Daniel Bernoulli la resolvió en ___.", "opts": ["1713", "1738", "1953"], "ans": "1738"}, {"s": "Cada rama de la apuesta aporta ___ lempira.", "opts": ["un", "dos", "medio"], "ans": "un"}, {"s": "La utilidad marginal del dinero es ___.", "opts": ["creciente", "decreciente", "constante"], "ans": "decreciente"}, {"s": "El primer límite del valor esperado es la apuesta ___.", "opts": ["única", "repetida", "barata"], "ans": "única"}, {"s": "El segundo límite es el riesgo de ___.", "opts": ["ruina", "inflación", "fraude"], "ans": "ruina"}, {"s": "Los axiomas de la utilidad esperada son de ___.", "opts": ["1944", "1953", "1979"], "ans": "1944"}, {"s": "Una decisión se juzga por su ___, no por su resultado.", "opts": ["proceso", "precio", "tamaño"], "ans": "proceso"}];
const explainQuestions=[{"q": "Explica en qué consiste la apuesta de San Petersburgo y por qué su valor esperado es infinito.", "ans": "Se lanza una moneda honrada hasta que sale cara: si sale al primer lanzamiento se pagan 2 lempiras, al segundo 4, al tercero 8, doblando siempre. La probabilidad de cada rama se divide por dos y el premio se multiplica por dos, así que cada rama aporta exactamente un lempira al valor del juego, y las ramas no terminan. La suma de infinitos unos no tiene tope: el valor esperado es infinito. Y aun así casi nadie paga cien lempiras por jugarlo."}, {"q": "¿Quién planteó la paradoja, quién la resolvió y por qué se llama de San Petersburgo?", "ans": "La planteó Nicolás Bernoulli en 1713, en una carta a Pierre Rémond de Montmort. La resolvió su primo Daniel Bernoulli en 1738, en un ensayo publicado en las actas de la Academia de Ciencias de San Petersburgo, donde entonces trabajaba. El nombre le viene del lugar de publicación de la solución, no del lugar donde se planteó el problema."}, {"q": "Explica la utilidad marginal decreciente con una cifra en lempiras.", "ans": "Lo que se pesa no es el dinero sino lo que ese dinero añade a quien lo recibe, y cada lempira nuevo añade un poco menos que el anterior. Diez mil lempiras en una casa donde hay cuatro mil multiplican el dinero por 3,5 y resuelven el mes; en una casa donde hay cuatrocientos mil son un 2,5% más y casi no se notan al día siguiente. Con esa vara, las ramas gigantescas de San Petersburgo pagan sumas enormes que cambian poco, y la suma infinita se vuelve un número modesto."}, {"q": "Escribe los dos límites del valor esperado y da un ejemplo de cada uno.", "ans": "El primero es la apuesta única: la media es lo que sale a la larga, y quien juega una sola vez recibe una rama y no un promedio. Ejemplo: la rifa del colegio, una vez al año, donde siete de cada ocho veces se pierde el boleto entero aunque la cuenta salga a favor. El segundo es el riesgo de ruina: si la rama mala impide jugar la vez siguiente, la serie se corta y ninguna ventaja compensa eso. Ejemplo: el préstamo de sesenta mil lempiras cuya rama mala deja una deuda impagable."}, {"q": "¿Qué diferencia hay entre una norma y un retrato en esta materia?", "ans": "La norma dice cómo convendría decidir: von Neumann y Morgenstern demostraron en 1944 que quien decide de forma coherente se comporta como si maximizara la utilidad esperada. El retrato dice cómo se decide de verdad: Allais mostró en 1953 que la gente prefiere en un orden que contradice esos axiomas, y siempre en la misma dirección. Confundirlas es el error más caro: quien toma la norma por retrato diseña reglas que nadie cumple, y quien toma el retrato por norma se queda sin manera de mejorar."}, {"q": "Una oferta tiene la cuenta a favor y su rama mala hundiría la casa. ¿Qué se hace, y por qué?", "ans": "No se acepta, o se parte la apuesta hasta que la rama mala deje de sacar a la casa de la mesa. La razón es que toda cuenta de promedio supone que hay una vez siguiente: si perder impide jugarla, la serie se corta ahí y el promedio que justificaba la decisión nunca llega a cobrarse. Partir el tamaño convierte una apuesta prohibida en una razonable sin cambiar una sola probabilidad, porque lo que cambia no es la cuenta: es que ahora hay repetición."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

