const evalTFBank=[{"q": "El valor esperado de la apuesta de San Petersburgo es infinito.", "a": true}, {"q": "Nicolás Bernoulli planteó la paradoja en 1713, en una carta a Montmort.", "a": true}, {"q": "La paradoja se llama de San Petersburgo porque allí se planteó por primera vez.", "a": false}, {"q": "Daniel Bernoulli publicó su solución en 1738.", "a": true}, {"q": "La utilidad marginal decreciente dice que cada lempira nuevo vale más que el anterior.", "a": false}, {"q": "Negarse a pagar cien lempiras por la apuesta de San Petersburgo es un error de cálculo.", "a": false}, {"q": "La ley de los grandes números la demostró Jacob Bernoulli en «Ars Conjectandi», obra póstuma de 1713.", "a": true}, {"q": "En una apuesta que se juega una sola vez, quien juega recibe el promedio.", "a": false}, {"q": "Si la rama mala impide jugar la vez siguiente, la serie se corta y el promedio deja de prometer nada.", "a": true}, {"q": "Von Neumann y Morgenstern publicaron sus axiomas de la utilidad esperada en 1944.", "a": true}, {"q": "La paradoja de Allais mostró que la gente viola esos axiomas con sistema.", "a": true}, {"q": "Un seguro tiene, para el asegurado, valor esperado positivo.", "a": false}, {"q": "Partir una apuesta en pedazos cambia sus probabilidades.", "a": false}, {"q": "Una decisión se juzga por su resultado y no por cómo se decidió.", "a": false}, {"q": "Maurice Allais recibió el Nobel de Economía en 1988.", "a": true}];
const evalMCBank=[{"q":"¿Cómo se juega la apuesta de San Petersburgo?","o":["a) Se lanza un dado y se paga la cara","b) Se lanza una moneda hasta que salga cara, doblando el premio","c) Se lanzan dos monedas a la vez","d) Se apuesta a un número entre uno y cien"],"a":1},{"q":"¿Por qué su valor esperado es infinito?","o":["a) Porque la banca no tiene límite de dinero","b) Porque la moneda está trucada","c) Porque cada rama aporta un lempira y las ramas no terminan","d) Porque el premio crece más rápido que la probabilidad baja"],"a":2},{"q":"¿Quién planteó la paradoja?","o":["a) Nicolás Bernoulli","b) Daniel Bernoulli","c) Jacob Bernoulli","d) Pierre Rémond de Montmort"],"a":0},{"q":"¿De dónde le viene el nombre a la paradoja?","o":["a) Del lugar donde Daniel Bernoulli publicó su solución","b) De un casino ruso del siglo XVIII","c) Del apellido de quien la planteó","d) De la ciudad donde vivía Montmort"],"a":0},{"q":"¿En qué consiste la solución de Daniel Bernoulli?","o":["a) En limitar el número de lanzamientos","b) En corregir el cálculo de las probabilidades","c) En prohibir los juegos con premio ilimitado","d) En pesar lo que el dinero añade a quien lo recibe, y no la cifra"],"a":3},{"q":"¿Qué nombre recibe hoy esa idea?","o":["a) Utilidad marginal decreciente","b) Ley de los grandes números","c) Criterio de Kelly","d) Teoría de las perspectivas"],"a":0},{"q":"¿Cuál es el primer límite del valor esperado?","o":["a) Que la media solo promete algo a quien repite","b) Que las probabilidades nunca se conocen","c) Que solo sirve con cifras pequeñas","d) Que exige conocer la utilidad"],"a":0},{"q":"¿Cuál es el segundo?","o":["a) La inflación","b) El costo de calcular","c) La aversión al riesgo","d) El riesgo de ruina, que corta la serie"],"a":3},{"q":"¿Qué demostró Jacob Bernoulli en «Ars Conjectandi»?","o":["a) La solución a la paradoja","b) Los axiomas de la utilidad esperada","c) La ley de los grandes números","d) El criterio para dimensionar apuestas"],"a":2},{"q":"¿Qué demuestra el teorema de von Neumann y Morgenstern?","o":["a) Que la gente maximiza la utilidad esperada","b) Que quien decide de forma coherente se comporta como si la maximizara","c) Que el valor esperado siempre es la respuesta","d) Que las preferencias son irracionales"],"a":1},{"q":"¿Qué mostró Allais en 1953?","o":["a) Que San Petersburgo no tiene solución","b) Que las preferencias reales contradicen esos axiomas, y en la misma dirección","c) Que la utilidad decreciente es falsa","d) Que las loterías son rentables"],"a":1},{"q":"¿Por qué conviene comprar un seguro aunque su valor esperado sea negativo?","o":["a) Porque las aseguradoras pierden dinero","b) Porque se cambia una pérdida chica y segura por evitar una enorme que saca de la mesa","c) Porque la probabilidad del daño es alta","d) Porque el precio siempre es justo"],"a":1},{"q":"Una oferta tiene la cuenta a favor pero su rama mala deja una deuda impagable. ¿Qué hace esta casa?","o":["a) Acepta, porque el promedio manda","b) Acepta si la probabilidad supera el 50%","c) No acepta, o parte la apuesta hasta que la rama mala no la saque de la mesa","d) Lo decide a suertes"],"a":2},{"q":"¿Qué logra partir una apuesta en pedazos?","o":["a) Mejorar las probabilidades","b) Aumentar el valor esperado","c) Eliminar el riesgo por completo","d) Que haya vez siguiente, sin cambiar ninguna probabilidad"],"a":3},{"q":"¿Cómo se juzga una decisión, según esta etapa?","o":["a) Por el resultado que dio","b) Por lo que opinen los demás","c) Por cómo se decidió y por lo que se sabía al decidir","d) Por cuánto dinero movió"],"a":2}];
const evalCPBank=[{"q": "Nicolás Bernoulli planteó la paradoja en el año ___.", "a": "1713"}, {"q": "Daniel Bernoulli publicó su solución en el año ___.", "a": "1738"}, {"q": "La ciudad que le da nombre a la paradoja es San ___.", "a": "Petersburgo"}, {"q": "En la apuesta, cada rama aporta ___ lempira al valor del juego.", "a": "un"}, {"q": "Que cada lempira nuevo valga menos se llama utilidad marginal ___.", "a": "decreciente"}, {"q": "El primer límite del valor esperado es la apuesta ___.", "a": "única"}, {"q": "El segundo límite es el riesgo de ___.", "a": "ruina"}, {"q": "La ley de los grandes ___ la demostró Jacob Bernoulli.", "a": "números"}, {"q": "Von Neumann y ___ publicaron sus axiomas en 1944.", "a": "Morgenstern"}, {"q": "Maurice ___ mostró en 1953 que la gente viola esos axiomas.", "a": "Allais"}, {"q": "Un ___ es una apuesta con la cuenta en contra que conviene comprar.", "a": "seguro"}, {"q": "Cuando la apuesta gusta pero el tamaño asusta, se ___ la apuesta.", "a": "parte"}, {"q": "Las probabilidades se escriben ___ de conocer el resultado.", "a": "antes"}, {"q": "Una decisión se juzga por el ___ con que se tomó, no por cómo cayó el dado.", "a": "proceso"}, {"q": "La carta de 1713 iba dirigida a Pierre Rémond de ___.", "a": "Montmort"}];
