// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y": "1", "icon": "🌳", "label": "Las ramas", "text": "Se escriben <strong>todos</strong> los resultados posibles, incluido el aburrido de que no pase nada. <strong>Se cae:</strong> listando solo la rama buena y la catastrófica, y dejando fuera la más probable, que casi siempre es «sale regular»."}, {"y": "2", "icon": "🎯", "label": "Las probabilidades", "text": "A cada rama se le pone un número, y al lado <strong>lo que sostiene ese número</strong>. <strong>Se cae:</strong> poniéndolas después de haber decidido, con lo cual la cuenta ya no decide nada: solo confirma."}, {"y": "3", "icon": "💵", "label": "Lo que gana o pierde cada rama", "text": "En lempiras, y también en lo que no son lempiras (horas, confianza, espacio de marca). <strong>Se cae:</strong> metiendo en la misma columna cosas que no se cambian por dinero, que es hacer trampa a favor del sí."}, {"y": "4", "icon": "🧮", "label": "El valor esperado", "text": "Cada rama por su probabilidad, y se suman. <strong>Se cae:</strong> creyendo que aquí termina la decisión. Aquí termina la aritmética; la decisión empieza en el paso siguiente."}, {"y": "5", "icon": "🔁", "label": "¿Esto se repite?", "text": "La media es lo que sale <strong>a la larga</strong>. <strong>Se cae:</strong> usando el promedio para una apuesta única, donde no se recibe un promedio sino una rama."}, {"y": "6", "icon": "💀", "label": "¿La rama mala nos saca de la mesa?", "text": "Si perder impide jugar la vez siguiente, la serie se corta y no hay ventaja que valga. <strong>Se cae:</strong> midiendo la pérdida en lempiras y no en «¿seguimos jugando?»."}, {"y": "7", "icon": "📓", "label": "Se escribe y se fecha", "text": "La hoja se guarda <strong>antes</strong> de conocer el resultado. <strong>Se cae:</strong> no escribiendo nada, y quedándose con la anécdota, que siempre le da la razón a quien la cuenta."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(pregunto){sfx(pregunto?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(pregunto){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🎯</span><span class="ms-text"><strong>Preguntaste pares sueltos y al azar:</strong> siete por ocho, siete por cuatro, siete por nueve. Angelly falló seis de veinte, y cada fallo se corrigió en el mismo segundo, antes de la pregunta siguiente.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🏺</span><span class="ms-text"><strong>Se practicó lo que después se pide:</strong> cada par quedó con su propia puerta de entrada, porque el intento participó en el resultado. A la semana contesta suelto y sin cantar.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🔁</span><span class="ms-text"><strong>La cantó veinte veces más:</strong> las veinte le salieron perfectas, porque cantada nunca falla. La sensación de dominio subió, y con razón: hizo muy bien lo que hizo.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">⏱️</span><span class="ms-text"><strong>Se reforzó la cadena, no el par:</strong> veinte repeticiones más de un solo orden. En la fila del mercado sigue tardando cinco segundos, porque para llegar al eslabón hay que arrancar desde el primero.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"esperado": {"nombre": "El valor esperado", "icon": "🧮", "estructura": {"title": "Qué es", "info": "• Pesar <strong>cada rama por su probabilidad</strong> y sumar<br>• Aritmética de escuela primaria: multiplicar y sumar<br>• Contesta una pregunta concreta: qué conviene <strong>a la larga</strong><br>• Cuatro piezas: las ramas, las probabilidades, lo que paga cada una, y la suma"}, "funcion": {"title": "Cómo se reconoce", "info": "• Aparece en cuanto hay <strong>números y una decisión</strong><br>• Se reconoce por su forma: tantas multiplicaciones como ramas<br>• Si alguien dice «en promedio conviene», está usando esto<br>• Y si nadie escribió las ramas, no lo está usando: lo está invocando"}, "enfermedades": {"title": "Dónde se cae", "info": "• Usarlo en una apuesta que ocurre <strong>una sola vez</strong><br>• Usarlo cuando la rama mala <strong>hunde la casa</strong><br>• Escribir las probabilidades después de decidir<br>• Olvidar una rama, casi siempre la de «no pasa nada»"}, "cuidados": {"title": "En esta casa", "info": "• Se calcula <strong>siempre</strong>, aunque después no mande<br>• Se escribe en la hoja de la apuesta, con fecha<br>• Y se acompaña de las dos preguntas de criterio, que no están en la fórmula"}}, "paradoja": {"nombre": "San Petersburgo", "icon": "🎲", "estructura": {"title": "Qué es", "info": "• Un juego: moneda hasta que salga cara, pagando 2, 4, 8, 16…<br>• Cada rama aporta lo mismo, y las ramas <strong>no se acaban</strong><br>• Valor esperado <strong>infinito</strong><br>• Planteado por Nicolás Bernoulli en 1713, en una carta a Montmort"}, "funcion": {"title": "Cómo se reconoce", "info": "• Por el resultado absurdo: la cuenta manda pagar cualquier precio<br>• Y por la reacción de cualquiera: nadie da cien lempiras<br>• Se llama así por San Petersburgo, donde Daniel Bernoulli publicó la salida en 1738<br>• Es el caso de laboratorio donde la herramienta se rompe"}, "enfermedades": {"title": "Dónde se cae", "info": "• Creer que quien se niega a pagar <strong>está fallando</strong><br>• Creer que es un acertijo sin consecuencias prácticas<br>• Olvidar que ninguna banca real puede pagar las ramas lejanas<br>• Usarlo para decir que las matemáticas no sirven, que es lo contrario de lo que enseña"}, "cuidados": {"title": "En esta casa", "info": "• Se usa como <strong>recordatorio</strong>: toda herramienta tiene condiciones de uso<br>• Y como prueba de que el estómago a veces ve algo que la cuenta no ve<br>• Cuando la cuenta y el estómago no coinciden, se escribe por qué"}}, "utilidad": {"nombre": "La utilidad", "icon": "💰", "estructura": {"title": "Qué es", "info": "• Lo que un dinero <strong>añade a quien lo recibe</strong>, no la cifra<br>• Cada lempira nuevo vale un poco menos que el anterior<br>• Daniel Bernoulli, 1738: la salida a la paradoja<br>• Von Neumann y Morgenstern la formalizaron en 1944"}, "funcion": {"title": "Cómo se reconoce", "info": "• Se nota al comparar la <strong>misma cifra en dos casas</strong><br>• Diez mil lempiras: un mes resuelto o un renglón olvidable<br>• Explica por qué se compran seguros perdiendo dinero en promedio<br>• Y por qué nadie apuesta la casa aunque la cuenta salga a favor"}, "enfermedades": {"title": "Dónde se cae", "info": "• Confundir la <strong>norma</strong> (cómo convendría decidir) con el <strong>retrato</strong> (cómo se decide)<br>• Creer que describe a la gente: Allais mostró en 1953 que no<br>• Usarla para justificar cualquier conducta después de ocurrida"}, "cuidados": {"title": "En esta casa", "info": "• Se usa para <strong>dimensionar</strong>: la misma oferta no vale igual en dos momentos<br>• Antes de comparar dos cifras se pregunta qué hay ya en la casa<br>• Y se acepta que el seguro es una apuesta con la cuenta en contra, comprada a propósito"}}, "ruina": {"nombre": "La ruina", "icon": "💀", "estructura": {"title": "Qué es", "info": "• La pérdida que <strong>impide jugar la vez siguiente</strong><br>• No es una pérdida grande: es una pérdida <strong>terminal</strong><br>• Corta la serie, y con ella toda promesa de la media<br>• No aparece en la fórmula del valor esperado"}, "funcion": {"title": "Cómo se reconoce", "info": "• Se reconoce con una pregunta, no con una cifra: <strong>¿seguimos jugando?</strong><br>• Suele esconderse detrás de una cuenta favorable<br>• Aparece cuando lo que se arriesga es lo que se necesita, no lo que sobra<br>• Y aparece también en lo que no es dinero: la confianza no se recompra"}, "enfermedades": {"title": "Dónde se cae", "info": "• Aceptar porque «en promedio conviene»<br>• Medir la rama mala en lempiras y no en consecuencias<br>• Repetir una apuesta buena con un tamaño que no aguanta una racha mala"}, "cuidados": {"title": "En esta casa", "info": "• Ninguna apuesta que pueda hundir la casa se acepta, <strong>por buena que sea la cuenta</strong><br>• Cuando la apuesta gusta pero el tamaño asusta, se <strong>parte en pedazos</strong><br>• Partir el tamaño convierte una apuesta prohibida en una razonable sin tocar ninguna probabilidad"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== LECTURAS (normas 5, 5-quater y 5-quinquies) =====================
// Seis textos (Borges, Cervantes, Harari, la entrevista de la casa, la
// conversación Quintero-Gala) con tres baterías: comprensión (25, cinco por
// voz), completar (10) y análisis complejo (10, sin XP a propósito). El motor
// es el de la referencia del escocés dorado, con los colores y el pie de esta
// misión. Las preguntas se contestan con los textos delante: son examen de
// lectura, no de memoria, que es exactamente la lección de la etapa.
const lectComprensionBank=[{"t":"Borges","q":"¿Qué heredó el narrador de su tío Aureliano?","o":["a) Una fortuna en monedas de oro","b) Una biblioteca completa","c) Un negocio de la casa comercial","d) Una casa con goteras, una deuda y un cuaderno de hule negro"],"c":3},{"t":"Borges","q":"¿Qué frase había escrita en la primera página del cuaderno?","o":["a) «El juego que vale infinito y no vale nada»","b) «Nadie sabe para quién trabaja»","c) «La suerte no perdona»","d) «Doce centavos»"],"c":0},{"t":"Borges","q":"¿Por qué había despedido el tío a su sobrino?","o":["a) Por llegar tarde","b) Por una discusión sobre el cuaderno","c) Por un error de doce centavos","d) Por jugar en horas de trabajo"],"c":2},{"t":"Borges","q":"Según el cuento, ¿a quién cita Daniel Bernoulli en su propio ensayo?","o":["a) A Gabriel Cramer, que había pensado antes algo parecido","b) A Jacob Bernoulli","c) A Pierre de Fermat","d) A su padre Johann"],"c":0},{"t":"Borges","q":"¿Qué anotó el tío después de rechazar la sociedad con R.?","o":["a) «Me equivoqué»","b) «Nunca más»","c) «Salió bien. No me arrepiento»","d) «Habría que haber aceptado»"],"c":2},{"t":"Cervantes","q":"¿Quiénes se guarecen en la venta aquella noche?","o":["a) Un cura, un barbero y un labrador","b) Dos estudiantes y un ventero","c) Un estudiante, un arriero y la ventera","d) Un caballero y su escudero"],"c":2},{"t":"Cervantes","q":"¿Cuánto ofrece el arriero por entrar en el juego?","o":["a) Cien reales","b) Dos reales","c) Nada","d) Ocho reales"],"c":1},{"t":"Cervantes","q":"¿Dónde escribe el estudiante su demostración?","o":["a) En un cuaderno","b) En la pared de la venta, con carbón","c) En la arena del camino","d) En una carta"],"c":1},{"t":"Cervantes","q":"Según la ventera, ¿en qué se diferencian las cuentas de los dos?","o":["a) En que uno multiplica y el otro suma","b) En que uno usa reales y el otro maravedís","c) En que uno cuenta un juego que se juega mil veces y el otro uno que se juega una sola","d) En que uno sabe latín y el otro no"],"c":2},{"t":"Cervantes","q":"¿Por qué dice la ventera que no daría los cien reales?","o":["a) Porque no cree en el juego","b) Porque son la harina del mes y quien se queda sin harina no juega la partida siguiente","c) Porque el estudiante no le cae bien","d) Porque prefiere prestarlos con interés"],"c":1},{"t":"Harari","q":"Según el ensayo, ¿cómo se manejaba el riesgo durante casi toda la historia humana?","o":["a) Con seguros comunales","b) Con tablas de probabilidad","c) Con augurios, ofrendas y amuletos","d) Con contratos escritos"],"c":2},{"t":"Harari","q":"¿Qué correspondencia se señala como el momento en que la pregunta por la probabilidad se hizo bien?","o":["a) La de Pascal y Fermat, en 1654","b) La de Newton y Leibniz","c) La de Nicolás Bernoulli y Montmort","d) La de Halley y Lloyd"],"c":0},{"t":"Harari","q":"¿Qué coincidencia de fechas subraya el ensayo?","o":["a) Que 1713 es a la vez el año de la ley de los grandes números y el del juego de la moneda","b) Que 1738 es el año de dos libros de Daniel Bernoulli","c) Que 1944 y 1953 están cerca","d) Que Halley y Lloyd publicaron el mismo año"],"c":0},{"t":"Harari","q":"Según el ensayo, ¿qué se compra al pagar un seguro?","o":["a) Seguir en la mesa","b) Dinero","c) Tranquilidad emocional","d) Un derecho legal"],"c":0},{"t":"Harari","q":"¿Qué institución nació del café de Edward Lloyd, abierto en 1688?","o":["a) La Equitable Life","b) El Banco de Inglaterra","c) La Royal Society","d) Lloyd's, donde se repartía el riesgo de los barcos"],"c":3},{"t":"Entrevista","q":"¿Con qué confesión empieza Punset la entrevista?","o":["a) Con que nunca entendió las matemáticas","b) Con que durante años repitió que la gente decide mal porque no sabe calcular","c) Con que no cree en la utilidad esperada","d) Con que su programa se acababa"],"c":1},{"t":"Entrevista","q":"¿Cómo formula Bernoulli su propia idea en la entrevista?","o":["a) Que el dinero no importa","b) Que hay que apostar siempre lo mismo","c) Que el bienestar que da un pequeño aumento de riqueza es inversamente proporcional a la riqueza que ya se posee","d) Que la probabilidad es subjetiva"],"c":2},{"t":"Entrevista","q":"¿Qué le concede Bernoulli a Punset sobre el juego llevado al infinito?","o":["a) Que su vara nunca falla","b) Que la solución de Cramer era mejor","c) Que la paradoja no tiene solución","d) Que si se insiste en llevar la vara al infinito, se rompe otra vez, y que ninguna banca real podría pagar las ramas lejanas"],"c":3},{"t":"Entrevista","q":"¿Qué ejemplo dice Bernoulli haber puesto en su propio ensayo?","o":["a) Un comerciante que manda mercancía por mar y se pregunta si asegurarla","b) Un jugador de cartas","c) Un labrador que siembra","d) Un prestamista"],"c":0},{"t":"Entrevista","q":"¿Qué episodio personal cuenta Bernoulli al final?","o":["a) Que su padre publicó un libro sobre la misma materia fechándolo como anterior al suyo","b) Su salida de San Petersburgo","c) Un premio que no le dieron","d) La muerte de su primo Nicolás"],"c":0},{"t":"Quintero y Gala","q":"¿Qué contesta Gala cuando Quintero le pregunta si ha apostado alguna vez?","o":["a) Que nunca","b) Que todos los días, y casi nunca con dinero","c) Que solo en la lotería","d) Que apostó una vez y perdió"],"c":1},{"t":"Quintero y Gala","q":"Según Gala, ¿qué compra quien juega a la lotería?","o":["a) Una inversión razonable","b) Una costumbre familiar","c) Una semana de imaginación, no un número","d) Un billete y nada más"],"c":2},{"t":"Quintero y Gala","q":"¿Qué ejemplo usa Gala para decir que la media no consuela al que juega una vez?","o":["a) Una cosecha","b) Un cirujano que dice que la operación sale bien en nueve de cada diez casos","c) Un viaje en barco","d) Una partida de cartas"],"c":1},{"t":"Quintero y Gala","q":"¿Cuál es, para Gala, la única palabra seria de la conversación?","o":["a) La suerte","b) La ruina","c) El dinero","d) El destino"],"c":1},{"t":"Quintero y Gala","q":"¿Cuáles son las dos reglas que Gala atribuye a su abuela?","o":["a) Ahorrar y no prestar","b) Jugar poco y jugar seguido","c) No jugar nunca y no fiarse de nadie","d) No jugar lo que se necesita, y no arrepentirse de la decisión si se escribieron antes las razones"],"c":3},{"t":"Debate","q":"¿Cuál es la pregunta en disputa del careo?","o":["a) Si la probabilidad existe","b) Si San Petersburgo tiene solución","c) Si conviene comprar seguros","d) Qué es exactamente lo que hay que maximizar al aceptar o rechazar una apuesta"],"c":3},{"t":"Debate","q":"¿Qué sostiene la defensa sobre el teorema de 1944?","o":["a) Que describe cómo decide la gente","b) Que sustituye a la idea de Bernoulli","c) Que solo vale para apuestas repetidas","d) Que es un teorema sobre coherencia, no una hipótesis sobre psicología"],"c":3},{"t":"Debate","q":"¿Cuál es el argumento central de la objeción?","o":["a) Que las probabilidades no se conocen","b) Que el valor esperado promedia mundos paralelos, y quien decide vive uno solo","c) Que los axiomas tienen un error lógico","d) Que la utilidad no se puede medir"],"c":1},{"t":"Debate","q":"¿Qué ejemplo numérico usa la objeción para mostrar que las pérdidas se multiplican?","o":["a) Doblar el premio en cada lanzamiento","b) Repartir cien entre ocho","c) Sumar uno por cada rama","d) Perder la mitad y después ganar la mitad, que deja un veinticinco por ciento menos"],"c":3},{"t":"Debate","q":"¿En qué coinciden las dos posturas, según el terreno común?","o":["a) En que el valor esperado del dinero a secas es un mal criterio y en que el riesgo de ruina es decisivo","b) En que la aversión al riesgo no existe","c) En que la utilidad esperada debe abandonarse","d) En que la disputa ya está resuelta"],"c":0}];
const lectCompletarBank=[{"t": "Borges", "q": "El cuaderno que hereda el narrador es de hule ___.", "a": "negro"}, {"t": "Borges", "q": "El tío Aureliano había sido cajero de una casa comercial durante treinta y ___ años.", "a": "un"}, {"t": "Cervantes", "q": "El estudiante escribe su demostración en la pared de la venta con ___.", "a": "carbón"}, {"t": "Cervantes", "q": "El arriero replica al estudiante que aquello «es no ___».", "a": "comer"}, {"t": "Harari", "q": "En 1693, Edmond ___ publicó una tabla de vida a partir de los registros de la ciudad de Breslavia.", "a": "Halley"}, {"t": "Harari", "q": "En 1762 se fundó en Londres la ___ Life, la primera que calculó las primas con tablas de mortalidad.", "a": "Equitable"}, {"t": "Entrevista", "q": "Bernoulli cuenta que publicó su «___» en 1738, el mismo año que el ensayo sobre la medida de la suerte.", "a": "Hydrodynamica"}, {"t": "Entrevista", "q": "Bernoulli despide la entrevista diciendo que ha venido de San Petersburgo y que todo lo demás fue el viaje ___.", "a": "corto"}, {"t": "Quintero y Gala", "q": "Gala dice que en la camilla no cabe una multitud: cabe un señor con ___.", "a": "miedo"}, {"t": "Quintero y Gala", "q": "Gala compara a quien hace bien las cuentas y pierde con un buen sembrador con mal año: no se le juzga por la cosecha, se le juzga por el ___.", "a": "surco"}, {"t": "Debate", "q": "El careo llama a la postura de la objeción la economía de la ___.", "a": "ergodicidad"}, {"t": "Debate", "q": "Según la defensa, maximizar el crecimiento a largo plazo equivale a maximizar el valor esperado del ___ del patrimonio.", "a": "logaritmo"}];
const lectAnalisisBank=[{"t": "Borges", "q": "El tío escribe «Salió bien. No me arrepiento» sobre una sociedad que rechazó. Explica por qué esa línea es lo contrario de la soberbia, y qué regla de la etapa está aplicando sin nombrarla.", "guia": "Se valora que se vea la inversión: el tío no se felicita por haber acertado, porque no acertó (el negocio salió bien y él dijo que no). Lo que está diciendo es que la decisión se juzga por cómo se tomó y por lo que se sabía entonces, no por cómo cayó el dado después. Una respuesta buena nombra el riesgo de ruina (perder la casa cortaba la serie) y observa que el narrador confundió la línea con soberbia justamente porque el mundo califica por el resultado. Se valora también quien note que la línea solo se sostiene porque las razones estaban escritas antes, con fecha."}, {"t": "Borges", "q": "El cuento termina diciendo que el infinito cabe en un cuaderno de hule negro y que la casa donde uno duerme no cabe. Explica esa imagen con las piezas de la etapa.", "guia": "Se valora que se lea la imagen como el contraste entre lo que la aritmética puede representar y lo que la aritmética no puede compensar. El infinito es una propiedad de la suma, y una suma cabe en un papel; la casa es la condición de seguir jugando, y no entra en ninguna columna porque no es una cantidad sino un requisito. Una respuesta buena conecta esto con los dos límites: la media promete a quien repite, y quien pierde la casa no repite. Se valora que se evite la lectura fácil de que las matemáticas no sirven: el cuento dice que sirven, y dice para qué."}, {"t": "Cervantes", "q": "La ventera dice que los dos tienen razón y que por eso se pelean. Explica en qué tiene razón cada uno y por qué las dos cuentas no son contradictorias.", "guia": "Se valora que se separen las dos preguntas. El estudiante contesta correctamente «cuánto vale este juego si se juega muchísimas veces», y su suma de unos es impecable. El arriero contesta correctamente «cuánto me conviene pagar si lo juego una vez», y su respuesta también es buena, porque tres de cada cuatro veces la partida termina pagando dos o cuatro reales. No hay contradicción: hay dos preguntas distintas con la misma moneda. Una respuesta buena nombra la ley de los grandes números como lo que hace verdadera la primera, y observa que el error está en creer que hay una sola pregunta."}, {"t": "Cervantes", "q": "La ventera añade un segundo argumento, el de la harina del mes, distinto del primero. Explica por qué es un argumento aparte y no una repetición.", "guia": "Se valora que se distinga repetición de tamaño. El primer argumento es sobre cuántas veces se juega; el segundo es sobre qué pasa si se pierde, y sería válido incluso si el juego se repitiera. Una respuesta buena señala que la ventera está formulando el riesgo de ruina en lenguaje de despensa: quien se queda sin harina no juega la partida siguiente, y por tanto la promesa del promedio se le corta. Se valora que se note que la ventera resuelve en dos frases lo que el estudiante no había visto con toda su aritmética, y que eso es lo contrario de un elogio de la ignorancia: es que la aritmética no contiene esas dos preguntas."}, {"t": "Harari", "q": "El ensayo subraya que 1713 es a la vez el año de la ley de los grandes números y el del juego de la moneda. Explica por qué esa coincidencia no es una anécdota.", "guia": "Se valora que se lea la coincidencia como la relación entre una herramienta y su límite. La ley de los grandes números es lo que da sentido a la palabra promedio: garantiza que lo observado se acerca a lo esperado si se repite mucho. El juego de la moneda es el caso donde esa garantía no ayuda, porque nadie va a jugarlo muchísimas veces y porque las ramas que sostienen el infinito son rarísimas. Una respuesta buena observa que la especie construyó la herramienta y encontró su frontera casi el mismo día, y que eso es lo normal en ciencia: el contraejemplo suele nacer pegado al teorema."}, {"t": "Harari", "q": "El ensayo dice que el seguro, visto con la aritmética sola, es un mal negocio para todos los asegurados, y visto con la idea de Bernoulli es excelente. Explica las dos miradas y por qué no se contradicen.", "guia": "Se valora que se maneje el signo del valor esperado sin confundirlo con la conveniencia. Con aritmética: la aseguradora tiene que ganar, luego el asegurado pierde en promedio, y eso es cierto. Con utilidad: se cambia una pérdida pequeña y segura por la desaparición de una pérdida enorme y rara, y como las pérdidas grandes duelen desproporcionadamente (porque sacan de la mesa), el cambio conviene. Una respuesta buena concluye que el signo del valor esperado no basta para decidir, ni a favor ni en contra, y que este es el ejemplo simétrico de la rifa: allí el signo era positivo y no convenía, aquí es negativo y conviene."}, {"t": "Entrevista", "q": "Bernoulli le dice a Punset que confundir la norma con el retrato es el defecto de su oficio, y confundir el retrato con la norma el del oficio de Punset. Explica los dos defectos y da un ejemplo de cada uno.", "guia": "Se valora que se entiendan las dos direcciones del error. El defecto del teórico es tomar su norma por una descripción: diseñar reglas, incentivos o políticas suponiendo que la gente decide coherentemente, y luego extrañarse de que nadie las cumpla. El defecto del observador es tomar el retrato por norma: concluir que, como la gente decide así, así está bien decidir, con lo cual desaparece toda posibilidad de mejorar. Una respuesta buena usa a Allais como bisagra: descubrir que la gente viola los axiomas deja abiertas dos preguntas distintas, si la regla estaba mal o si la gente puede aprender a cumplirla, y casi nadie se toma la molestia de separarlas."}, {"t": "Entrevista", "q": "Bernoulli concede sin pelear que su vara se rompe si el juego se lleva al infinito, y dice que eso enseña otra cosa. Explica qué enseña y por qué la concesión fortalece su posición en vez de debilitarla.", "guia": "Se valora que se vea el movimiento intelectual. Bernoulli no defiende que su solución sea universal: la declara buena para las cantidades con las que vive una persona, que es para lo que la propuso. Lo que la objeción muestra, dice, no es que la vara sea mala sino que ninguna cuenta debería llevarse al infinito, porque no hay bancas ni vidas infinitas: su propia banca no podría pagar la rama cuarenta. Una respuesta buena observa que declarar el alcance de una herramienta la vuelve más fiable, no menos, y que esa es la misma regla que la casa aplica al valor esperado cuando le exige sus dos condiciones de uso."}, {"t": "Quintero y Gala", "q": "Gala dice que quien compra lotería no está comprando un número sino una semana, y que el error es de quien le dice que hace una mala inversión. Explica ese argumento y discútelo con las piezas de la etapa.", "guia": "Se valora que se reconstruya el argumento antes de juzgarlo: si lo que se compra es una semana de imaginación, entonces el valor esperado del premio no es la magnitud relevante, porque el bien adquirido no es el premio. Se valora igualmente que se le ponga el límite: el argumento se sostiene mientras el precio sea pequeño respecto de lo que hay en la casa, y deja de sostenerse en cuanto lo que se gasta es la harina del mes, que es el caso de mucha gente que juega. Una respuesta buena usa la utilidad decreciente para decir por qué el mismo billete es barato en una casa y caro en otra."}, {"t": "Quintero y Gala", "q": "Explica la imagen final de Gala (el buen sembrador con mal año frente al que encuentra una moneda en la calle) y qué regla de la etapa está diciendo.", "guia": "Se valora que se identifique la regla del proceso: la decisión se juzga por cómo se tomó y no por su resultado. El sembrador hizo bien el surco y el año salió malo: proceso bueno, resultado malo. El que encuentra la moneda no hizo nada y le fue bien: proceso inexistente, resultado bueno. Una respuesta buena observa que el mundo califica por el resultado, que por eso hace falta un tribunal distinto, y que ese tribunal es la hoja escrita antes y fechada. Se valora también quien note que Gala llega a la misma conclusión que el cajero del cuento por un camino completamente distinto."}, {"t": "Debate", "q": "Reconstruye las dos posturas del careo en su mejor versión y di qué le concede cada una a la otra.", "guia": "Se valora que las dos queden bien escritas antes de opinar, que es la regla del acero. La defensa: el teorema de 1944 no es una hipótesis psicológica sino un resultado sobre coherencia, sirve para decisiones únicas y sin dinero, y el criterio del crecimiento en el tiempo coincide con maximizar la utilidad logarítmica, que ya está en Bernoulli desde 1738. La objeción: el valor esperado promedia mundos paralelos y quien decide vive uno solo; con patrimonio multiplicativo el promedio del conjunto y lo que le pasa a la persona típica difieren; y no hace falta postular aversión al riesgo para explicar por qué se rechaza una apuesta justa. Concesiones: la objeción concede que no hay grieta lógica en el teorema y que en el caso más citado las cuentas coinciden; la defensa concede que la motivación importa porque manda a los investigadores a laboratorios distintos."}, {"t": "Debate", "q": "El careo termina diciendo que las dos partes darían el mismo consejo a una familia con un préstamo sobre la mesa. Explica por qué, y qué se aprende de que una disputa de cimientos no cambie la recomendación práctica.", "guia": "Se valora que se identifique el terreno común: las dos rechazan el valor esperado del dinero a secas, las dos aceptan que la escala importa y las dos tratan el riesgo de ruina como decisivo. De ahí que ante un préstamo cuya rama mala deja una deuda impagable las dos digan que no. Una respuesta buena extrae la lección de método: que dos teorías rivales coincidan en la recomendación significa que el desacuerdo está en la fundamentación y no en el tejado, y que quien tiene que decidir hoy no necesita esperar a que la disputa se cierre. Se valora también que se nombre qué dato la resolvería: una situación donde las dos predicciones se separen y se pueda medir cuál acierta."}];
